//! Migration runners. Each schema crate embeds one ordered list (`MIGRATIONS`, generated by
//! `sqlcheck`). A mirror tracks its version in `PRAGMA user_version`, the control DB in a
//! `_migrations` table. Production only rolls forward: a database newer than the build is refused.

use crate::copy::suffixed;
use rusqlite::{Connection, ErrorCode, OpenFlags, OptionalExtension, TransactionBehavior};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    /// Runs on the existing file.
    InPlace,
    /// Mirrors only (`NNNN_name.rebuild.sql`): the change needs data the mirror doesn't hold, so
    /// a mirror behind it is replaced by an empty one and re-imported.
    Rebuild,
}

#[derive(Debug)]
pub struct Migration {
    pub version: u32,
    pub name: &'static str,
    pub kind: Kind,
    pub sql: &'static str,
}

/// What a mirror at version `file` (`None`: no file) needs to reach the end of `migs`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Plan {
    Current,
    InPlace {
        from: u32,
        to: u32,
    },
    /// Build an empty mirror at the current version, then import.
    Create {
        why: String,
    },
    /// The file is newer than this build: refuse it.
    TooNew {
        db: u32,
        build: u32,
    },
}

pub fn plan(file: Option<u32>, migs: &[Migration]) -> Plan {
    let to = migs.len() as u32;
    match file {
        None | Some(0) => Plan::Create {
            why: "no mirror file".into(),
        },
        Some(v) if v == to => Plan::Current,
        Some(v) if v > to => Plan::TooNew { db: v, build: to },
        Some(v) => match migs[v as usize..].iter().find(|m| m.kind == Kind::Rebuild) {
            Some(m) => Plan::Create {
                why: format!("migration {:04}_{} needs a re-import", m.version, m.name),
            },
            None => Plan::InPlace { from: v, to },
        },
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MigError {
    /// Disk full, I/O, busy: the same migration may work later. The file is unchanged.
    Transient(String),
    /// Anything the data or the SQL causes: it will fail again. The file is unchanged.
    Failed(String),
}

impl std::fmt::Display for MigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            MigError::Transient(e) | MigError::Failed(e) => f.write_str(e),
        }
    }
}

fn classify(e: rusqlite::Error) -> MigError {
    match e.sqlite_error_code() {
        Some(
            ErrorCode::DiskFull
            | ErrorCode::SystemIoFailure
            | ErrorCode::DatabaseBusy
            | ErrorCode::DatabaseLocked
            | ErrorCode::CannotOpen
            | ErrorCode::OutOfMemory,
        ) => MigError::Transient(e.to_string()),
        _ => MigError::Failed(e.to_string()),
    }
}

/// The mirror's `user_version`, or `None` when there's no file. `Mirrors` reads it on a lane
/// reader (`user_version`); this opens its own connection, for tools and tests.
pub fn file_version(path: &Path) -> Result<Option<u32>, MigError> {
    if !path.exists() {
        return Ok(None);
    }
    let c = Connection::open_with_flags(
        path,
        OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NO_MUTEX,
    )
    .map_err(classify)?;
    user_version(&c).map(Some).map_err(classify)
}

/// A connection's `user_version`: a database file's schema version.
pub fn user_version(c: &Connection) -> rusqlite::Result<u32> {
    c.pragma_query_value(None, "user_version", |r| r.get(0))
}

impl From<rusqlite::Error> for MigError {
    fn from(e: rusqlite::Error) -> Self {
        classify(e)
    }
}

impl From<crate::Error> for MigError {
    fn from(e: crate::Error) -> Self {
        classify_job(e)
    }
}

/// How a mirror job's error reads to the gate: a busy cap, an I/O error, a SQLite error that
/// may clear, or the drain's seal (the next start does the job) is transient, anything else
/// won't.
pub(crate) fn classify_job(e: crate::Error) -> MigError {
    match e {
        crate::Error::Sqlite(e) => classify(e),
        e @ (crate::Error::Unavailable { .. } | crate::Error::Io(_) | crate::Error::Sealed) => {
            MigError::Transient(e.to_string())
        }
        e => MigError::Failed(e.to_string()),
    }
}

/// Every pending migration and the new `user_version` in one `BEGIN IMMEDIATE` transaction, so
/// a failure leaves the file exactly as it was. Then the planner's statistics are brought up to
/// date (`pool::optimize`).
pub fn migrate_in_place(
    conn: &mut Connection,
    migs: &[Migration],
    from: u32,
    to: u32,
) -> Result<(), MigError> {
    let tx = conn
        .transaction_with_behavior(TransactionBehavior::Immediate)
        .map_err(classify)?;
    for m in &migs[from as usize..to as usize] {
        tx.execute_batch(m.sql).map_err(|e| match classify(e) {
            MigError::Failed(s) => MigError::Failed(format!("{:04}_{}: {s}", m.version, m.name)),
            t => t,
        })?;
    }
    tx.pragma_update(None, "user_version", to)
        .map_err(classify)?;
    tx.commit().map_err(classify)?;
    // New indexes have no statistics yet. They only steer the planner: a failure here keeps the
    // migration.
    let _ = crate::pool::optimize(conn);
    Ok(())
}

/// An empty mirror at the build's version, built beside `path` and renamed over it, so a crash
/// leaves either the old file or the new one. Every connection to `path` must be closed first.
pub fn create_fresh(path: &Path, migs: &[Migration]) -> Result<(), crate::Error> {
    let tmp = PathBuf::from(format!("{}.new", path.display()));
    for f in [tmp.clone(), suffixed(&tmp, "-wal"), suffixed(&tmp, "-shm")] {
        let _ = std::fs::remove_file(f);
    }
    let mut c = Connection::open(&tmp)?;
    c.pragma_update(None, "journal_mode", "WAL")?;
    let tx = c.transaction()?;
    for m in migs {
        tx.execute_batch(m.sql)?;
    }
    tx.pragma_update(None, "user_version", migs.len() as u32)?;
    tx.commit()?;
    // Fold the WAL into the file so the rename moves everything.
    c.pragma_update(None, "wal_checkpoint", "TRUNCATE")?;
    drop(c);
    for ext in ["-wal", "-shm"] {
        let _ = std::fs::remove_file(suffixed(path, ext));
        let _ = std::fs::remove_file(suffixed(&tmp, ext));
    }
    std::fs::rename(&tmp, path)?;
    Ok(())
}

#[derive(Debug, PartialEq, Eq)]
pub enum ControlOutcome {
    Current(u32),
    Migrated {
        from: u32,
        to: u32,
        backup: Option<PathBuf>,
    },
}

/// The control DB isn't disposable, so it never rebuilds. It migrates at startup, before
/// `/readyz`: a `VACUUM INTO` backup in `backup_dir` first (unless the DB is new), then every
/// pending migration in one transaction, each recorded in `_migrations`. A newer DB is
/// `Error::TooNew`; a failed step is `Error::MigrationFailed` and leaves the DB as it was.
///
/// Foreign keys are off while the steps run, so a table rebuild (create, copy, drop, rename)
/// doesn't cascade the drop into child tables, and `foreign_key_check` must pass before commit.
pub fn migrate_control(
    conn: &mut Connection,
    migs: &[Migration],
    backup_dir: &Path,
) -> Result<ControlOutcome, crate::Error> {
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS _migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at TEXT NOT NULL DEFAULT (datetime('now')))",
    )?;
    let to = migs.len() as u32;
    let db: u32 = conn.query_row(
        "SELECT coalesce(max(version), 0) FROM _migrations",
        [],
        |r| r.get(0),
    )?;
    if db > to {
        return Err(crate::Error::TooNew { db, build: to });
    }
    if db == to {
        return Ok(ControlOutcome::Current(db));
    }
    let backup = if db > 0 {
        let path = backup_dir.join(format!("control-before-v{to}.db"));
        // Whole and on disk before anything is migrated.
        let vacuum = || -> Result<(), crate::Error> {
            std::fs::create_dir_all(backup_dir)?;
            crate::copy::write_whole(&path, |tmp| {
                conn.execute("VACUUM INTO ?1", [tmp.to_string_lossy()])?;
                Ok(())
            })
        };
        vacuum().map_err(|e| crate::Error::BackupFailed(e.to_string()))?;
        Some(path)
    } else {
        None
    };
    conn.pragma_update(None, "foreign_keys", false)?;
    let migrated = run_control_steps(conn, &migs[db as usize..]);
    conn.pragma_update(None, "foreign_keys", true)?;
    migrated?;
    Ok(ControlOutcome::Migrated {
        from: db,
        to,
        backup,
    })
}

fn run_control_steps(conn: &mut Connection, steps: &[Migration]) -> Result<(), crate::Error> {
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    for m in steps {
        tx.execute_batch(m.sql).map_err(|e| {
            crate::Error::MigrationFailed(format!("{:04}_{}: {e}", m.version, m.name))
        })?;
        tx.execute(
            "INSERT INTO _migrations (version, name) VALUES (?1, ?2)",
            (m.version, m.name),
        )?;
    }
    let dangling: Option<String> = tx
        .query_row(
            "SELECT \"table\" FROM pragma_foreign_key_check LIMIT 1",
            [],
            |r| r.get(0),
        )
        .optional()?;
    if let Some(table) = dangling {
        return Err(crate::Error::MigrationFailed(format!(
            "a foreign key in {table} points at a missing row"
        )));
    }
    tx.commit()?;
    Ok(())
}
